# area: inheritance_mro
# hypothesis: in a diamond hierarchy super() follows the C3 MRO so the shared base runs exactly once, and an override that narrows a parameter type is an LSP violation that checkers must reject.
from typing import reveal_type


class Base:
    def label(self, trail: list[str]) -> list[str]:
        trail.append('Base')
        return trail


class Left(Base):
    def label(self, trail: list[str]) -> list[str]:
        trail.append('Left')
        return super().label(trail)


class Right(Base):
    def label(self, trail: list[str]) -> list[str]:
        trail.append('Right')
        return super().label(trail)


class Diamond(Left, Right):
    def label(self, trail: list[str]) -> list[str]:
        trail.append('Diamond')
        return super().label(trail)


class Narrow(Base):
    def label(self, trail: list[int]) -> list[str]:  # expect-error: parameter type narrowed (LSP)
        return [str(trail)]


d = Diamond()
reveal_type(d.label([]))
print(d.label([]))
print([c.__name__ for c in Diamond.__mro__])
print(Narrow().label([1]))
